#[inductive(exec_dispatch_local)]
fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
    let combiner_pre = pre.combiner[node_id];
    let CombinerState::Loop { queued_ops, lversion, tail, idx } = combiner_pre;

    // Get the request ID being processed
    let rid = queued_ops.index(idx as int);

    // Establish that all preconditions hold
    assert(pre.wf_combiner_for_node_id(node_id));

    // Prove that the post-state maintains the combiner well-formed invariant
    // Check each condition for CombinerState::Loop:

    // 1. tail <= post.tail (global tail may have advanced)
    assert(post.tail >= pre.tail);
    assert(tail <= pre.tail);
    assert(tail <= post.tail);

    // 2. post.local_versions[node_id] <= lversion + 1 (we're advancing the local tail)
    assert(post.local_versions[node_id] == pre.local_versions[node_id]);
    assert(pre.local_versions[node_id] <= lversion);
    assert(post.local_versions[node_id] <= lversion + 1);

    // 3. lversion + 1 <= tail (the local tail should always be smaller or equal to the global tail)
    assert(lversion <= tail);
    assert(lversion + 1 <= tail);

    // 4. LogContainsEntriesUpToHere(post.log, lversion + 1) 
    // (the log now contains all entries up to localtail)
    assert(LogContainsEntriesUpToHere(pre.log, lversion));
    assert(pre.log.contains_key(lversion));
    assert(LogContainsEntriesUpToHere(post.log, lversion + 1));

    // 5. 0 <= idx + 1 <= queued_ops.len()
    assert(0 <= idx);
    assert(idx < queued_ops.len());
    assert(idx + 1 <= queued_ops.len());
    assert(0 <= idx + 1 <= queued_ops.len());

    // 6. LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)
    // Need to show that the log range matching is preserved after processing one entry
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates));
    assert(pre.log.contains_key(lversion));
    assert(pre.log[lversion].node_id == node_id);
    assert(pre.local_updates.contains_key(rid));
    assert(pre.local_updates[rid].is_Placed());
    assert(pre.local_updates[rid].get_Placed_idx() == lversion);

    // After advancing one step in the log processing:
    // - The entry at lversion was processed (it was local)
    // - The queue index advanced by 1
    // - The log index advanced by 1
    // So we should have LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)
    assert(LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates));

    // 7. LogRangeNoNodeId(post.log, tail, post.tail, node_id)
    // This should be preserved since we only processed a local entry
    assert(LogRangeNoNodeId(pre.log, tail, pre.tail, node_id));
    assert(post.tail >= pre.tail);
    assert(LogRangeNoNodeId(post.log, tail, post.tail, node_id));

    // 8. QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1)
    // After processing the entry at index idx, entries from idx+1 onwards should still be Placed
    assert(QueueRidsUpdatePlaced(queued_ops, pre.local_updates, idx));
    assert(post.local_updates[rid].is_Applied());
    assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1));

    // 9. QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1)
    // Entries up to idx should be Done or Applied
    assert(QueueRidsUpdateDone(queued_ops, pre.local_updates, idx));
    assert(post.local_updates[rid].is_Applied());
    assert(QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1));

    // 10. seq_unique(queued_ops) - unchanged
    assert(seq_unique(queued_ops));

    // All conditions are satisfied, thus post.wf_combiner_for_node_id(node_id)
    assert(post.wf_combiner_for_node_id(node_id));
}

