#[inductive(exec_dispatch_local)]
fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
    // The pre-state combiner is in Loop state by transition precondition
    let CombinerState::Loop { queued_ops, lversion, tail, idx } = pre.combiner[node_id];

    // Get the request ID being processed
    let rid = queued_ops.index(idx as int);

    // From the pre-invariant, we know:
    assert(pre.wf_combiner_for_node_id(node_id));

    // Show that each condition for the post-state Loop still holds:

    // 1. tail <= post.tail (global tail may have advanced)
    assert(post.tail == pre.tail); // Transition doesn't change tail
    assert(tail <= post.tail);

    // 2. post.local_versions[node_id] <= lversion + 1
    assert(post.local_versions[node_id] == pre.local_versions[node_id]);
    assert(pre.local_versions[node_id] <= lversion); // from pre-condition
    assert(post.local_versions[node_id] <= lversion + 1);

    // 3. lversion + 1 <= tail
    assert(lversion <= tail); // from pre-condition
    assert(lversion + 1 <= tail); // need to prove this

    // 4. LogContainsEntriesUpToHere(post.log, lversion + 1)
    assert(LogContainsEntriesUpToHere(pre.log, lversion)); // from pre-condition
    assert(pre.log.contains_key(lversion)); // from pre log complete invariant 
    assert(post.log == pre.log); // Transition doesn't change log
    assert(LogContainsEntriesUpToHere(post.log, lversion + 1));

    // 5. 0 <= idx + 1 <= queued_ops.len()
    assert(0 <= idx); // from pre-condition
    assert(idx < queued_ops.len()); // from pre-condition
    assert(0 <= idx + 1 <= queued_ops.len());

    // 6. LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)
    // This is the key condition to prove
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates));

    // The update for rid transitions from Placed to Applied
    assert(pre.local_updates.contains_key(rid));
    assert(pre.local_updates[rid].is_Placed());
    assert(pre.local_updates[rid].get_Placed_idx() == lversion);

    // Post-state has the update in Applied state
    assert(post.local_updates.contains_key(rid));
    assert(post.local_updates[rid].is_Applied());
    assert(post.local_updates[rid].get_Applied_idx() == lversion);

    // All other updates remain unchanged
    assert(forall|other_rid| #![auto] other_rid != rid && pre.local_updates.contains_key(other_rid)
        ==> post.local_updates.contains_key(other_rid) && post.local_updates[other_rid] == pre.local_updates[other_rid]);

    // Now we need to show that the LogRangeMatchesQueue still holds
    // We can use the helper lemma that shows this property is preserved under update changes
    assert(LogRangeMatchesQueue_update_change(
        queued_ops,
        post.log,
        idx,
        lversion,
        tail,
        node_id,
        pre.local_updates,
        post.local_updates
    ));

    // 7. LogRangeNoNodeId(post.log, tail, post.tail, node_id)
    // LogRangeNoNodeId should be preserved
    assert(LogRangeNoNodeId(pre.log, tail, pre.tail, node_id));
    assert(post.log == pre.log);
    assert(post.tail == pre.tail);
    assert(LogRangeNoNodeId(post.log, tail, post.tail, node_id));

    // 8. QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1)
    // Entries from idx+1 onwards should still be Placed
    assert(QueueRidsUpdatePlaced(queued_ops, pre.local_updates, idx));
    // Entry at idx is now Applied, so it's no longer Placed
    assert(post.local_updates[rid].is_Applied());
    // But entries from idx+1 onwards are still Placed
    assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1));

    // 9. QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1)
    // Entries up to idx should now include the newly Applied entry
    assert(QueueRidsUpdateDone(queued_ops, pre.local_updates, idx));
    assert(post.local_updates[rid].is_Applied()); 
    assert(QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1));

    // 10. seq_unique(queued_ops) - unchanged
    assert(seq_unique(queued_ops));

    // All conditions satisfied for post.wf_combiner_for_node_id(node_id)
    assert(post.wf_combiner_for_node_id(node_id));
}

