#[inductive(exec_dispatch_local)]
fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
    // This transition processes a local entry in the log.
    // The pre invariant tells us: pre.wf_combiner_for_node_id(node_id).
    // In particular, the CombinerState::Loop case tells us:
    //   LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates)

    let CombinerState::Loop { queued_ops, lversion, tail, idx } = pre.combiner[node_id];

    // The RID that this transition processes
    let rid: ReqId = queued_ops.index(idx as int);

    // Preconditions ensure that:
    assert(pre.wf_combiner_for_node_id(node_id));

    // The combiner moves from Loop { queued_ops, lversion, tail, idx }
    // to Loop { queued_ops, lversion + 1, tail, idx + 1}

    // Pre-condition: lversion < tail (ensures there's a log entry to process)
    assert(lversion < tail);

    // Pre logs properties:
    assert(LogContainsEntriesUpToHere(pre.log, lversion));
    assert(pre.log.contains_key(lversion));
    assert(pre.log[lversion].node_id == node_id); // Processing local log entry

    // The update state for rid transitions from Placed to Applied
    assert(pre.local_updates.contains_key(rid));
    assert(pre.local_updates[rid].is_Placed());
    assert(pre.local_updates[rid].get_Placed_idx() == lversion);

    assert(post.local_updates.contains_key(rid));
    assert(post.local_updates[rid].is_Applied());
    assert(post.local_updates[rid].get_Applied_idx() == lversion);

    // Everything else is unchanged between pre and post
    assert(post.log == pre.log);
    assert(post.tail == pre.tail);
    assert(post.local_versions[node_id] == pre.local_versions[node_id]);

    // Verify each post invariant separately:

    // 1. tail <= post.tail (tail is not modified in this transition)
    assert(tail <= post.tail);

    // 2. lversion + 1 >= post.local_versions[node_id]
    assert(post.local_versions[node_id] <= lversion + 1);

    // 3. lversion + 1 <= tail
    assert(lversion < tail); // Precondition
    assert(lversion + 1 <= tail);

    // 4. LogContainsEntriesUpToHere(post.log, lversion + 1)
    assert(LogContainsEntriesUpToHere(post.log, lversion));
    assert(post.log.contains_key(lversion));
    assert(LogContainsEntriesUpToHere(post.log, lversion + 1));

    // 5. 0 <= idx + 1 <= queued_ops.len()
    assert(0 <= idx);
    assert(idx < queued_ops.len());
    assert(idx + 1 <= queued_ops.len());
    assert(0 <= idx + 1 <= queued_ops.len());

    // 6. LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)
    // This requires careful proof using helper lemmas
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates));

    // Apply the appropriate helper lemma showing that changing an update state from
    // Placed to Applied preserves the LogRangeMatchesQueue property when advancing indices.
    // Since this transition processes a log entry and we advance both idx and lversion by 1,
    // this corresponds to moving past one matched item in the recursive definition of LogRangeMatchesQueue.

    // The key insight is that we consume one entry in the LogRangeMatchesQueue recursion.
    // The precondition ensures that log.entry[lversion].node_id == node_id, so it's a "local" entry.
    // Therefore, the recusrive case of LogRangeMatchesQueue requires advancement of both indices.
    // 
    // We also know that:
    //   - pre.local_updates[rid].is_Placed() and get_Placed_idx() == lversion 
    //   - post.local_updates[rid].is_Applied() and get_Applied_idx() == lversion
    // So the constraint is still met.

    // Since we're moving past one matched entry, the remaining part of the LogRangeMatchesQueue should hold.
    assert(LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates));

    // 7. LogRangeNoNodeId(post.log, tail, post.tail, node_id)
    assert(LogRangeNoNodeId(pre.log, tail, pre.tail, node_id));
    assert(post.log == pre.log);
    assert(post.tail == pre.tail);
    assert(LogRangeNoNodeId(post.log, tail, post.tail, node_id));

    // 8. QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1)
    assert(QueueRidsUpdatePlaced(queued_ops, pre.local_updates, idx));
    assert(post.local_updates[rid].is_Applied()); // No longer in Placed state
    assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1));

    // 9. QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1)
    assert(QueueRidsUpdateDone(queued_ops, pre.local_updates, idx));
    assert(post.local_updates[rid].is_Applied()); // Now satisfies the Done/Appled requirement
    assert(QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1));

    // 10. seq_unique(queued_ops) - unchanged
    assert(seq_unique(queued_ops));

    // Thus post.wf_combiner_for_node_id(node_id) holds
    assert(post.wf_combiner_for_node_id(node_id));
}

