fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Pre combiner state must be Loop
    let CombinerState::Loop { queued_ops, lversion, tail, idx } = pre.combiner[node_id];
    let rid = queued_ops.index(idx as int);

    // Known preconditions
    assert(pre.wf_combiner_for_node_id(node_id));  // This includes LogRangeMatchesQueue(..., idx, lversion, ...)
    assert(pre.log.contains_key(lversion));
    assert(pre.log[lversion].node_id == node_id);  // Processing a local log entry
    assert(pre.local_updates.contains_key(rid));
    assert(pre.local_updates[rid].is_Placed());
    assert(pre.local_updates[rid].get_Placed_idx() == lversion);

    // The post state
    assert(post.local_updates.contains_key(rid));
    assert(post.local_updates[rid].is_Applied());
    assert(post.local_updates[rid].get_Applied_idx() == lversion);

    // Other components are unchanged
    assert(post.log == pre.log);
    assert(post.tail == pre.tail);
    assert(post.local_versions[node_id] == pre.local_versions[node_id]);

    // Proving that post combiner state is also valid

    // Conditions 1-5 and 7-10 are straightforward (follow from preservation):
    assert(tail <= post.tail);
    assert(post.local_versions[node_id] <= lversion + 1);
    assert(lversion + 1 <= tail);
    assert(LogContainsEntriesUpToHere(post.log, lversion + 1));
    assert(0 <= idx + 1 <= queued_ops.len());
    assert(LogRangeNoNodeId(post.log, tail, post.tail, node_id));
    assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1));
    assert(QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1));
    assert(seq_unique(queued_ops));

    // The critical condition is: 
    // LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)
    // Given that we are processing the local entry at position lversion (idx-th entry in queue):
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates));

    // The key is to use the recursive definition directly
    // Looking at the definition of LogRangeMatchesQueue for when logIndexLower < logIndexUpper:        
    // &&& log.contains_key(logIndexLower)
    // &&& (log.index(logIndexLower).node_id == nodeId ==> {     // local case
    //     &&& queueIndex < queue.len()
    //     &&& updates.contains_key(queue.index(queueIndex as int))
    //     &&& updates.index(queue.index(queueIndex as int)).is_Placed()
    //     &&& updates.index(queue.index(queueIndex as int)).get_Placed_idx() == logIndexLower
    //     &&& LogRangeMatchesQueue(queue, log, queueIndex + 1, logIndexLower + 1, logIndexUpper, nodeId, updates)})

