    // We need a tighter argument. Let's consider the actual requirement:
    assert(forall|other_rid| #[trigger] pre.local_updates.contains_key(other_rid) 
        ==> (other_rid == rid || (post.local_updates.contains_key(other_rid) && post.local_updates[other_rid] == pre.local_updates[other_rid])));

