#[inductive(exec_dispatch_local)]
fn exec_dispatch_local_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Pre combiner state must be Loop
    let CombinerState::Loop { queued_ops, lversion, tail, idx } = pre.combiner[node_id];
    let rid = queued_ops.index(idx as int);

    // Known preconditions from pre invariant
    assert(pre.wf_combiner_for_node_id(node_id));

    // From the definition of wf_combiner_for_node_id(Loop):
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates));
    assert(pre.log.contains_key(lversion));
    assert(pre.log[lversion].node_id == node_id); // Processing local log entry

    // Update state transition
    assert(pre.local_updates.contains_key(rid));
    assert(pre.local_updates[rid].is_Placed());
    assert(pre.local_updates[rid].get_Placed_idx() == lversion);
    assert(post.local_updates.contains_key(rid));
    assert(post.local_updates[rid].is_Applied());
    assert(post.local_updates[rid].get_Applied_idx() == lversion);

    // Other state remains unchanged
    assert(post.log == pre.log);
    assert(post.tail == pre.tail);
    assert(post.local_versions[node_id] == pre.local_versions[node_id]);

    // Prove combiner wf property holds for post state

    // Conditions that follow directly from preservation:
    assert(tail <= post.tail);
    assert(post.local_versions[node_id] <= lversion + 1);
    assert(lversion + 1 <= tail); 
    assert(LogContainsEntriesUpToHere(post.log, lversion + 1));
    assert(0 <= idx + 1 <= queued_ops.len());
    assert(LogRangeNoNodeId(post.log, tail, post.tail, node_id));
    assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, idx + 1));
    assert(QueueRidsUpdateDone(queued_ops, post.local_updates, idx + 1));
    assert(seq_unique(queued_ops));

    // Critical case: LogRangeMatchesQueue needs to be preserved
    // Since we're processing the current entry (local) and moving indices forward,
    // we're consuming one step from the recursion.

    // The key insight is that since pre.log[lversion].node_id == node_id (local entry)
    // and the update at idx in the queue is Placed with idx=lversion,
    // the recursive definition of LogRangeMatchesQueue applies:
    //     LogRangeMatchesQueue(queued_ops, pre.log, idx, lversion, tail, node_id, pre.local_updates)
    //  == pre.log.contains_key(lversion) 
    //     && pre.log[lversion].node_id == node_id  // local entry
    //     && idx < queued_ops.len()  
    //     && pre.local_updates.contains_key(queued_ops[idx])
    //     && pre.local_updates[queued_ops[idx]].is_Placed()
    //     && pre.local_updates[queued_ops[idx]].get_Placed_idx() == lversion
    //     && LogRangeMatchesQueue(queued_ops, pre.log, idx + 1, lversion + 1, tail, node_id, pre.local_updates)
    //
    // All of these were established, which implies:
    assert(LogRangeMatchesQueue(queued_ops, pre.log, idx + 1, lversion + 1, tail, node_id, pre.local_updates));

    // But we need to show:
    // LogRangeMatchesQueue(queued_ops, post.log, idx + 1, lversion + 1, tail, node_id, post.local_updates)

    // This requires showing that changing just rid's update state
    // from Placed to Applied doesn't affect the tail portion of LogRangeMatchesQueue
    // (because we start from idx + 1, not idx)

    // For all entries that matter:
    assert(forall|j| #![auto] idx + 1 <= j < queued_ops.len() ==> (
        pre.local_updates.contains_key(queued_ops[j]) 
        && post.local_updates.contains_key(queued_ops[j])
        && post.local_updates[queued_ops[j]] == pre.local_updates[queued_ops[j]])
    );

    // Also, entries that have already been processed (0..idx) are not queried in 
    // LogRangeMatchesQueue(queued_ops, ..., idx + 1, ...) anyway.

    // We can use the update change lemma for this scenario:
    assert(LogRangeMatchesQueue_update_change_2(
        queued_ops, 
        post.log, 
        idx + 1,  
        lversion + 1, 
        tail, 
        node_id, 
        pre.local_updates, 
        post.local_updates));

    // Therefore all conditions for post.wf_combiner_for_node_id(node_id) hold
    assert(post.wf_combiner_for_node_id(node_id));
}

